"""Timesheet rows: one line per worker, busiest first."""

from collections import Counter
from typing import List

from hourglass.models import Shift
from hourglass.schedule import worker_minutes

def _checked(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    if any(not shift.worker.strip() for shift in shifts):
        raise ValueError("a shift has a blank worker name")

def _ranked(shifts: List[Shift]) -> List[tuple]:
    counts = Counter(shift.worker for shift in shifts)
    totals = worker_minutes(shifts)
    names = sorted(totals)
    names.sort(key=totals.get, reverse=True)
    return [
        (name, counts[name], totals[name]) for name in names
    ]

# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """Name, shift count and hours for each worker."""
    _checked(shifts)
    return [
        f"{name}: {count} shifts, {mins / 60:.1f} hours"
        for name, count, mins in _ranked(shifts)
    ]

