import unittest

from hourglass.models import Shift, Span
from hourglass.schedule import load_schedule
from hourglass.timesheet import timesheet_lines
from tests.support import data_file

class TimesheetTests(unittest.TestCase):
    def setUp(self):
        path = data_file("schedule.csv")
        self.shifts = load_schedule(path)

    def test_busiest_workers_first(self):
        self.assertEqual(
            timesheet_lines(self.shifts),
            [
                "Brisa: 3 shifts, 9.0 hours",
                "Quill: 2 shifts, 7.5 hours",
                "Odell: 2 shifts, 6.5 hours"
            ]
        )

    def test_equal_hours_sorted_by_name(self):
        shifts = [
            Shift("Zed", "mon", Span(540, 600)),
            Shift("Amy", "mon", Span(540, 600))
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Amy: 1 shifts, 1.0 hours",
                "Zed: 1 shifts, 1.0 hours"
            ]
        )

    def test_hours_to_one_decimal(self):
        shifts = [Shift("Amy", "mon", Span(540, 560))]
        self.assertEqual(
            timesheet_lines(shifts),
            ["Amy: 1 shifts, 0.3 hours"]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_name_raises(self):
        shifts = [Shift("  ", "mon", Span(540, 600))]
        with self.assertRaises(ValueError):
            timesheet_lines(shifts)
